function power(){return buildings.reduce((a,b)=>{if(b.team!==0||b.buildRemaining>0)return a;let p=defs[b.type].power;if(p>0)a.cap+=p;else a.used-=p;return a},{cap:40,used:0})}
function notify(t){$('#notice').textContent=t;noticeTimer=5;}
function productionFacility(t){return defs[t].naval?'marina':defs[t].air?'airfield':(t==='infantry'||defs[t].infantry)?'barracks':t==='harvester'?'command':'factory';}
function producible(b){if(!b||!b.building||b.buildRemaining>0)return [];return {command:['harvester'],barracks:['infantry','rocket','sniper'],factory:['tank','harvester','scout','artillery'],airfield:['helicopter','plane','bomber','fighter'],marina:['gunboat','destroyer']}[b.type]||[];}
