function canConstruct(type){if(type==='command')return selected[0]?.type==='harvester'&&!selected[0].pendingBuild;if(type==='factory')return buildings.some(b=>b.team===0&&b.type==='barracks'&&!b.buildRemaining&&b.hp>0);if(type==='airfield')return buildings.some(b=>b.team===0&&b.type==='factory'&&!b.buildRemaining&&b.hp>0);return true;}
function prerequisiteText(type){return type==='airfield'?'Requires completed vehicle shop':type==='command'?'Select an available harvester':'Requires completed barracks';}
function renderCards(){if(tab==='research'){renderResearch();return;}const b=selected[0];let list=tab==='build'?['plant','refinery','barracks','factory','airfield','turret','aa','silo','marina']:producible(b);$('#cards').innerHTML=list.map(t=>`<button class="card" data-type="${t}" ${tab==='build'&&!canConstruct(t)?'disabled':''}><span class="icon">${defs[t].icon}</span><span><b>${defs[t].name}</b><small>◆ ${defs[t].cost} · ${tab==='build'?(!canConstruct(t)?prerequisiteText(t):buildTimes[t]+'s build'):defs[t].time+'s production'}</small></span></button>`).join('');if(tab==='units'&&!list.length)$('#cards').innerHTML='<p class="production-help">'+(b?.buildRemaining>0?'Construction in progress. Production unlocks when complete.':b?.type==='silo'?'Missile silo selected. Use Launch rocket below.':'Select a completed command center, barracks, vehicle factory, or airfield to see its units.')+'</p>';document.querySelectorAll('.card').forEach(button=>button.onclick=()=>{let t=button.dataset.type;if(tab==='build'){if(!canConstruct(t))return notify(prerequisiteText(t));if(money<defs[t].cost)return notify('Insufficient minerals.');placement=t;missileTarget=null;rallyTarget=null;notify('Choose clear ground for '+defs[t].name+'.');}else enqueue(t,selected[0]);});}
function launchMissile(silo,target){if(!buildings.includes(silo)||silo.type!=='silo'||silo.buildRemaining>0)return notify('Select a completed missile silo.');if(silo.cool>0)return notify('Missile reload: '+Math.ceil(silo.cool)+'s.');if(power().used>power().cap)return notify('Restore power before launch.');if(money<150)return notify('Rocket requires 150 minerals.');if(target.x<0||target.y<0||target.x>=MAP_SIZE||target.y>=MAP_SIZE)return notify('Choose a target inside the map.');money-=150;silo.cool=25;playSound('rocket');missiles.push({from:{x:silo.x,y:silo.y},target:{...target},elapsed:0,duration:4.5});missileTarget=null;notify('Rocket launched. Impact in 4.5 seconds.');}
function impactRocket(m){playSound('tank');invalidateNavigation();blasts.push({x:m.target.x,y:m.target.y,life:1.2});for(const o of [...units,...buildings]){if(defs[o.type].air)continue;const d=dist(o,m.target);if(d<4.5)damageFeedback(null,o,Math.round((o.building?650:1600)*Math.max(.15,1-d/4.5)));}for(const t of trees)if(dist(t,m.target)<4.5)t.crushed=true;for(let i=0;i<50;i++)particles.push({x:m.target.x,y:m.target.y,z:rand(2,60),life:rand(.4,1.4),vx:rand(-4,4),vy:rand(-4,4),color:i%3?'#ffbf64':'#e76c3f'});notify('Rocket impact! Ground damage includes friendly forces.');}
