function box(x,y,w,d,h,color,z=0){if(voxelScale){const v=voxelScale;x=v.x+(x-v.x)*v.scale;y=v.y+(y-v.y)*v.scale;w*=v.scale;d*=v.scale;h*=v.scale;z=(z-(v.baseZ||0))*v.scale+(v.baseZ||0);}const positions=[[x-w/2,y-d/2],[x+w/2,y-d/2],[x+w/2,y+d/2],[x-w/2,y+d/2]].map(p=>rotateVoxelPoint(p[0],p[1]));const top=positions.map(p=>project(p.x,p.y,z+h)),bottom=positions.map(p=>project(p.x,p.y,z));const c=voxelRotation?.c??1,s=voxelRotation?.s??0,normals=[[s,-c],[c,s],[-s,c],[-c,-s]];for(let i=0;i<4;i++){const n=normals[i];if(n[0]+n[1]>.00001){const j=(i+1)%4;poly([top[i],top[j],bottom[j],bottom[i]],shade(color,.64+.16*Math.max(0,n[1])));}}poly(top,color);}
