function queueFor(building){return building?.building?queue.filter(q=>q.producer===building):[];}
function updateProduction(dt,ratio){const active=new Set(),completed=new Set();for(const q of queue){const b=q.producer||buildings.find(b=>b.type===q.required&&b.team===0);if(!b||!buildings.includes(b)||b.buildRemaining>0||active.has(b))continue;q.producer=b;active.add(b);q.progress+=dt*ratio;if(q.progress>=defs[q.type].time){const spawn=waterSpawn(b,q.type);if(!spawn){q.progress=defs[q.type].time;continue;}const born=addUnit(q.type,spawn.x,spawn.y);if(b.rally)born.target={...b.rally};completed.add(q);}}queue=queue.filter(q=>!completed.has(q));}
function groundVehicleModel(o,color,light,metal){const x=o.x,y=o.y,scout=o.type==='scout';if(scout)voxelScale={x,y,scale:.86};for(let side of [-1,1]){box(x+side*.36,y,.18,1.12,4,'#25343d',1);for(let i=0;i<27;i++){box(x+side*.36,y-.53+i*.04,.2,.025,1,metal,5);for(let j=0;j<3;j++)box(x+side*.465,y-.5+i*.037,.022,.027,.8,j%2?'#687d8a':'#a2aeb4',1+j*1.35);}for(let i=0;i<7;i++){box(x+side*.46,y-.44+i*.145,.025,.1,2.5,'#738793',1.2);box(x+side*.48,y-.43+i*.145,.025,.025,.8,light,2.1);}}
for(let layer=0;layer<4;layer++)box(x,y-.02,.7-layer*.055,.98-layer*.055,1.8,layer%2?color:metal,6+layer*1.8);for(let i=0;i<9;i++)for(let j=0;j<14;j++)box(x+(i-4)*.061,y+(j-6.5)*.062,.045,.042,.6,(i+j)%7?color:metal,13.3);
if(scout){box(x,y-.2,.4,.46,4,'#84bfd1',14);for(let i=0;i<6;i++)box(x-.2+i*.08,y-.45,.025,.04,4,metal,14);box(x+.18,y+.2,.035,.035,13,metal,15);}else{for(let i=-4;i<=4;i++)for(let j=-4;j<=4;j++)if(i*i+j*j<=18)box(x+i*.058,y+j*.058,.053,.053,4,(i+j)%5?color:metal,14);const length=o.type==='artillery'?1.25:.8;for(let i=0;i<16;i++)box(x,y-.2-i*length/16,.09+(i%4===0?.025:0),length/17,2.4,i%4?metal:color,18);box(x,y-.2-length,.15,.14,3,'#566b78',17.7);for(let i=-2;i<=2;i++)for(let j=-2;j<=2;j++)if(i*i+j*j<7)box(x+i*.04,y+.08+j*.04,.035,.035,1,metal,18.3);box(x+.2,y+.12,.04,.04,9,metal,17);}
for(let side of [-1,1]){for(let i=0;i<10;i++)box(x+side*.25,y+.15+i*.03,.035,.018,.8,'#20353e',14);box(x+side*.27,y-.49,.08,.06,1.8,'#f2ebad',11);}voxelScale=null;}

